import {clamp,easeInOut,blink} from './animation.js';
import {leaf,line,oval,shadow,star} from './shapes.js';

// Heroes deliberately have separate anatomies. Shared helpers only describe botanical
// materials (roots, eyes and volume), never a shared "hero body".
const PALETTES={
 vanguard:{dark:'#245b3b',mid:'#58b95d',light:'#a9ed79',leaf:'#347c48',accent:'#d7ff9b',glow:'#8dff78',outline:'#193d31'},
 warden:{dark:'#8d5b25',mid:'#e4a934',light:'#ffe582',leaf:'#4f914d',accent:'#fff3b2',glow:'#ffe06c',outline:'#59482a'},
 brawler:{dark:'#573659',mid:'#99528d',light:'#d990c0',leaf:'#3f7546',accent:'#f6c8a9',glow:'#ef8bc5',outline:'#35283b'},
 sentinel:{dark:'#276d67',mid:'#50a88e',light:'#9bd7ad',leaf:'#397967',accent:'#d7f6da',glow:'#8cebd3',outline:'#204744'},
 controller:{dark:'#315d59',mid:'#5db9a2',light:'#a6efd0',leaf:'#397967',accent:'#dfb4e8',glow:'#7ff7d5',outline:'#253f42'}
};
const height={vanguard:42,warden:48,brawler:31,sentinel:57,controller:52};
function path(c,draw,fill,stroke='#20382d',width=1.8){c.beginPath();draw();c.fillStyle=fill;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=width;c.lineJoin='round';c.lineCap='round';c.stroke()}}
function gradient(c,x0,y0,x1,y1,a,b){const g=c.createLinearGradient(x0,y0,x1,y1);g.addColorStop(0,a);g.addColorStop(1,b);return g}
function root(c,x,y,size,p,angle=0){c.save();c.translate(x,y);c.rotate(angle);path(c,()=>{c.moveTo(-size*.2,-2);c.bezierCurveTo(-size*.7,0,-size,4,-size*1.15,6);c.bezierCurveTo(-size*.4,7,size*.4,5,size,2);c.bezierCurveTo(size*.35,-1,0,-3,-size*.2,-2)},p.mid,p.outline,1.5);line(c,[[-size*.5,3],[size*.5,2]],p.light,.7);c.restore()}
function plantEye(c,x,y,p,{scale=1,look=0,angry=0,blinkValue=1}={}){oval(c,x,y,3.8*scale,4.7*scale*blinkValue,'#fff9d9');if(blinkValue>.25)oval(c,x+look,y+.2,1.55*scale,2.25*scale,p.outline,false);if(angry)line(c,[[x-4*scale,y-5*scale],[x+4*scale,y-6*scale+angry*2]],p.outline,1.6)}
function stem(c,points,width,p){line(c,points,p.outline,width+3);line(c,points,gradient(c,0,-30,12,20,p.light,p.dark),width)}
function heroLeaf(c,x,y,size,angle,p,color=p.leaf){leaf(c,x,y,size,angle,color)}
function cue(h,key,max){return clamp((h[key]||0)/max)}
function state(h,time){const moving=Math.hypot(h.velocityX||0,h.velocityY||0)>.05,reduce=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches;return{moving,step:reduce?0:Math.sin(time*(moving?11:2.4)+h.uid),idle:reduce?0:Math.sin(time*2+h.uid*.7),blink:blink(time,h.uid),attack:cue(h,'attackCue',h.id==='brawler'?.3:.25),ability:cue(h,'abilityCue',.8),hit:cue(h,'hitCue',.2),vy:clamp((h.velocityY||0)/2,-1,1)}}

function drawVanguard(c,h,time,s,p){const run=s.moving?s.step:0,recoil=easeInOut(s.attack),cast=s.ability>0,down=h.downed;let headY=down?4:-25+(s.moving?Math.abs(run)*-2:s.idle);c.save();if(down)c.rotate(-.28);c.rotate((s.moving?.09:0)*-Math.sign(h.velocityX||h.facing||1)+s.vy*.035);root(c,-8+run*4,15,10,p,-.1);root(c,9-run*4,15,10,p,.1);heroLeaf(c,-7,7,11,-1.05+run*.12,p,p.dark);stem(c,[[0,12],[-2,-5],[1-recoil*3,headY+7]],7,p);heroLeaf(c,-7,-7,10,-1.35-run*.12,p);heroLeaf(c,5,-3,9,.7+run*.1,p,p.mid);heroLeaf(c,-7,headY+7,8,-1.25,p,p.dark);
 c.save();c.translate(-recoil*5,headY);const pod=gradient(c,-15,-15,15,13,p.light,p.dark);path(c,()=>{c.moveTo(-15,5);c.bezierCurveTo(-18,-10,-7,-18,7,-16);c.bezierCurveTo(17,-14,20,-5,17,4);c.bezierCurveTo(12,14,-7,15,-15,5)},pod,p.outline,2.4);path(c,()=>{c.moveTo(10,-9);c.bezierCurveTo(19,-11,28,-8,31,-2);c.bezierCurveTo(29,7,19,10,10,7);c.bezierCurveTo(15,2,15,-4,10,-9)},p.mid,p.outline,2.2);oval(c,28,-1,7+recoil*2,6+recoil,p.outline,false);oval(c,27,-2,4.2+recoil,3.4,p.dark,false);plantEye(c,-3,-5,p,{look:2,angry:recoil,blinkValue:s.blink});plantEye(c,6,-5,p,{look:2,angry:recoil,blinkValue:s.blink});line(c,[[-11,7],[-4,10],[5,9]],p.light,1);if(s.attack>0){c.globalAlpha=s.attack;star(c,36,-1,6,p.glow,time*8);line(c,[[17,-12],[24,-16]],p.glow,1.4)}c.restore();if(cast){c.globalAlpha=cast*.8;for(let i=0;i<3;i++)line(c,[[-19-i*5,-22+i*6],[-27-i*5,-22+i*6]],p.glow,2)}c.restore()}

function petal(c,a,r,size,p,flare=0,wilt=0){c.save();c.rotate(a+wilt*.12);c.translate(0,-r);c.rotate(-a);path(c,()=>{c.moveTo(0,5);c.bezierCurveTo(-size*.72,1,-size*.62,-size*.9,0,-size*1.2);c.bezierCurveTo(size*.75,-size*.75,size*.78,1,0,5)},gradient(c,-size,0,size,0,p.dark,p.light),p.outline,1.35);c.restore()}
function drawWarden(c,h,time,s,p){const step=s.moving?s.step:0,cast=s.ability,down=h.downed,headY=down?-21:-31+(s.idle*.6);root(c,-6+step*2,15,7,p);root(c,7-step*2,15,7,p);stem(c,[[0,13],[0,-11],[0,headY+5]],6,p);heroLeaf(c,-3,-2,13,-1.35-step*.1,p,p.leaf);heroLeaf(c,4,2,12,.85+step*.12,p,p.mid);c.save();c.translate(0,headY);if(down)c.rotate(.28);for(let i=0;i<11;i++)petal(c,i*Math.PI*2/11+(i%2)*.035,15+cast*4,6.4+(i%3)*.7,p,cast,down?1:0);if(cast){c.globalAlpha=.18+cast*.25;oval(c,0,0,25+cast*8,25+cast*8,p.glow,false)}oval(c,0,0,12.5,13,gradient(c,-10,-10,10,12,p.light,p.dark));plantEye(c,-4,-2,p,{scale:.78,blinkValue:s.blink,angry:h.hp/h.maxHp<.35?.4:0});plantEye(c,4,-2,p,{scale:.78,blinkValue:s.blink,angry:h.hp/h.maxHp<.35?.4:0});line(c,[[-3,5],[0,7],[4,4]],p.outline,1.3);for(let i=0;i<5;i++)oval(c,-7+i*3.5,9+(i%2),.7,.7,p.accent,false);if(s.attack){c.globalAlpha=s.attack;star(c,0,15,5,p.glow,time*5)}c.restore()}

function tooth(c,x,y,flip,p){path(c,()=>{c.moveTo(x-3,y);c.lineTo(x,y+flip*7);c.lineTo(x+3,y)},p.accent,p.outline,1)}
function drawBrawler(c,h,time,s,p){const step=s.moving?s.step:0,snap=easeInOut(s.attack),cast=s.ability,down=h.downed;root(c,-14+step*3,13,11,p,-.2);root(c,14-step*3,13,11,p,.2);for(let i=0;i<3;i++)heroLeaf(c,-13+i*12,5,12,-1.6+i*.7+step*.08,p,i===1?p.dark:p.leaf);c.save();c.translate(snap*5,down?5:-5-Math.abs(step)*(s.moving?2:0)+cast*4);c.scale(1+cast*.12,1-cast*.08);for(const q of [-1,1])heroLeaf(c,-17,q*2,10,-1.8-q*.2,p,p.dark);path(c,()=>{c.moveTo(-20,1);c.bezierCurveTo(-24,-16,-8,-24,8,-20);c.bezierCurveTo(23,-17,27,-5,20,3);c.bezierCurveTo(10,-1,-8,-1,-20,1)},gradient(c,-15,-18,15,5,p.light,p.dark),p.outline,2.6);path(c,()=>{c.moveTo(-20,2);c.bezierCurveTo(-14,18,12,20,22,3);c.bezierCurveTo(8,7,-7,8,-20,2)},p.mid,p.outline,2.6);path(c,()=>{c.moveTo(-16,1);c.quadraticCurveTo(1,10,18,2);c.quadraticCurveTo(2,-4,-16,1)},'#6d304f',p.outline,1.4);const gape=2+snap*7;for(const x of [-11,-3,6,14])tooth(c,x,1-gape*.15,1,p);for(const x of [-7,2,11])tooth(c,x,5+gape*.25,-1,p);plantEye(c,-6,-11,p,{scale:.85,look:1,angry:1,blinkValue:s.blink});plantEye(c,5,-12,p,{scale:.85,look:1,angry:1,blinkValue:s.blink});if(s.attack){c.globalAlpha=s.attack;line(c,[[24,-8],[32,-13]],p.accent,2);line(c,[[25,3],[34,6]],p.accent,2)}c.restore();if(cast){c.globalAlpha=cast;for(let i=0;i<7;i++){const a=i*Math.PI*2/7;path(c,()=>{c.moveTo(Math.cos(a)*23,10+Math.sin(a)*8);c.lineTo(Math.cos(a)*34,10+Math.sin(a)*14);c.lineTo(Math.cos(a+.12)*23,10+Math.sin(a+.12)*8)},i%2?p.accent:'#aa744c',null)}}}

function thorn(c,x,y,a,p,size=3){c.save();c.translate(x,y);c.rotate(a);path(c,()=>{c.moveTo(-2,0);c.lineTo(0,-size*2);c.lineTo(2,0)},p.accent,p.outline,.7);c.restore()}
function drawSentinel(c,h,time,s,p){const step=s.moving?s.step:0,recoil=s.attack*3,cast=s.ability,down=h.downed;c.save();if(down)c.rotate(.42);root(c,-5+step,15,7,p);root(c,6-step,15,7,p);path(c,()=>{c.moveTo(-8,12);c.bezierCurveTo(-10,-2,-9,-30,-4,-42);c.quadraticCurveTo(0,-49,5,-42);c.bezierCurveTo(10,-26,9,-2,8,12);c.quadraticCurveTo(0,17,-8,12)},gradient(c,-8,-20,9,-20,p.light,p.dark),p.outline,2.4);path(c,()=>{c.moveTo(-6,-10);c.lineTo(-16-recoil,-10);c.quadraticCurveTo(-20,-11,-19,-16);c.lineTo(-18,-26);c.quadraticCurveTo(-14,-29,-12,-25);c.lineTo(-12,-18);c.lineTo(-6,-18)},p.mid,p.outline,2);path(c,()=>{c.moveTo(7,-19);c.lineTo(15,-19);c.lineTo(15,-28);c.quadraticCurveTo(20,-30,20,-25);c.lineTo(20,-13);c.quadraticCurveTo(14,-9,7,-11)},p.dark,p.outline,2);for(let y=-37;y<8;y+=10){thorn(c,-8,y,-1.4,p);thorn(c,8,y,1.4,p)}heroLeaf(c,3,-43,6,.5,p,'#d886b3');plantEye(c,-3,-27,p,{scale:.72,look:1,angry:1,blinkValue:s.blink});plantEye(c,4,-27,p,{scale:.72,look:1,angry:1,blinkValue:s.blink});line(c,[[-3,-18],[4,-18]],p.outline,1.4);if(cast){c.globalAlpha=.35+.45*cast;line(c,[[0,10],[0,-48]],p.glow,3);for(let y=-38;y<3;y+=9)star(c,0,y,2.5,p.glow,time)}if(s.attack){c.globalAlpha=s.attack;line(c,[[-23-recoil,-10],[-34-recoil,-10]],p.glow,2)}c.restore()}

function vine(c,points,p,width=3){line(c,points,p.outline,width+2);line(c,points,p.mid,width)}
function drawController(c,h,time,s,p){const step=s.moving?s.step:0,recoil=s.attack*3,cast=s.ability,down=h.downed;c.save();if(down)c.rotate(-.38);root(c,-6+step*2,15,8,p,-.2);root(c,7-step*2,15,8,p,.2);stem(c,[[0,13],[-2,-8],[3,-30]],6,p);vine(c,[[-1,-5],[-16,-13-step],[-20,-28]],p,3);heroLeaf(c,-15,-14,9,-1.2,p,p.dark);vine(c,[[3,-4],[15,-12],[20,-25+recoil]],p,3);heroLeaf(c,15,-12,9,.85,p,p.leaf);c.save();c.translate(3,down?-26:-35+s.idle);c.rotate(-.12+cast*.08);path(c,()=>{c.moveTo(-11,5);c.bezierCurveTo(-18,-5,-10,-20,1,-22);c.bezierCurveTo(14,-19,17,-6,10,8);c.quadraticCurveTo(0,15,-11,5)},gradient(c,-10,-15,12,10,p.accent,p.dark),p.outline,2.2);for(let i=0;i<4;i++){c.rotate(.8);path(c,()=>{c.moveTo(-1,7);c.bezierCurveTo(-9,0,-7,-9,1,-12);c.bezierCurveTo(7,-6,7,2,-1,7)},i%2?p.light:p.mid,p.outline,1.1)}plantEye(c,-3,-2,p,{scale:.7,look:1,angry:.45,blinkValue:s.blink});plantEye(c,4,-3,p,{scale:.7,look:1,angry:.45,blinkValue:s.blink});c.restore();if(cast){c.globalAlpha=.65*cast;for(let i=0;i<5;i++){const a=i*1.25+time;heroLeaf(c,Math.cos(a)*24,-10+Math.sin(a)*14,4,a,p,p.glow)}}if(s.attack){c.globalAlpha=s.attack;star(c,23-recoil,-25,5,p.glow,time*4)}c.restore()}

const renderers={vanguard:drawVanguard,warden:drawWarden,brawler:drawBrawler,sentinel:drawSentinel,controller:drawController};
function marker(c,id,p,y){c.save();c.translate(0,y);c.globalAlpha=.9;path(c,()=>{c.moveTo(0,-5);c.lineTo(5,0);c.lineTo(0,5);c.lineTo(-5,0)},p.dark,p.accent,1);heroLeaf(c,0,2.5,3,-.4,p,p.light);c.restore()}
export function drawHero(c,h,x,y,time){const p=PALETTES[h.id]||PALETTES.vanguard,s=state(h,time),wide=h.id==='brawler'?25:h.id==='sentinel'?12:18;c.save();c.translate(x,y);shadow(c,0,17,wide);c.scale(h.facing||1,1);const hitScale=1+s.hit*.07;c.scale(hitScale,1-s.hit*.08);renderers[h.id]?.(c,h,time,s,p);c.restore();c.save();c.translate(x,y);if(s.hit){c.globalAlpha=s.hit*.42;c.fillStyle=p.light;c.beginPath();c.ellipse(0,-height[h.id]/2,wide,height[h.id]/2,0,0,Math.PI*2);c.fill()}const barY=24;c.fillStyle=p.outline;c.fillRect(-20,barY,40,4);c.fillStyle=h.downed?'#d37b80':p.mid;c.fillRect(-19,barY+1,38*Math.max(0,h.hp/h.maxHp),2);if(h.downed){c.fillStyle='#f7dfd0';c.font='bold 8px system-ui';c.textAlign='center';c.fillText('DOWNED',0,38)}else marker(c,h.id,p,-height[h.id]-9);c.restore()}

function portrait(id){const h={id,uid:19,hp:1,maxHp:1,facing:1,velocityX:0,velocityY:0,attackCue:0,abilityCue:0,hitCue:0};return h}
export function drawHeroPortrait(c,id,x=50,y=55,size=1){const p=PALETTES[id],g=c.createRadialGradient(x,y-8,4,x,y,46);g.addColorStop(0,p.light+'88');g.addColorStop(1,p.dark+'22');c.fillStyle=g;c.beginPath();c.arc(x,y,45,0,Math.PI*2);c.fill();c.save();c.beginPath();c.arc(x,y,43,0,Math.PI*2);c.clip();c.translate(x,y+30);const scales={vanguard:1.45,warden:1.3,brawler:1.55,sentinel:1.25,controller:1.32};c.scale(scales[id]*size,scales[id]*size);renderers[id](c,portrait(id),.7,{moving:false,step:0,idle:0,blink:1,attack:id==='vanguard'?.25:0,ability:0,hit:0,vy:0},p);c.restore();c.strokeStyle=p.accent;c.lineWidth=3;c.beginPath();c.arc(x,y,44,0,Math.PI*2);c.stroke()}
const portraits=new Map();
export function heroImage(id){if(portraits.has(id))return portraits.get(id);const canvas=document.createElement('canvas');canvas.width=canvas.height=100;drawHeroPortrait(canvas.getContext('2d'),id);const image=canvas.toDataURL();portraits.set(id,image);return image}
